INSERT INTO dsl_rolling_diag_c26c5c6a0208.rolling_averages_v1 SELECT 'stock-20060104-20260414-v1','306f333e28c82c9f2c634d8a1eb64eb49d3092937d8ca7d2742d96ecdcf21a95','a460a741b13b2cea6066c7a973c246463d68c6eb083c07a50650ed8403f3ab17',a.bizdate,a.mktcode,a.tgtcode,a.ma20,a.ma60,a.ma120,a.ma250 FROM (SELECT * FROM (SELECT b.mktcode,b.tgtcode,b.bizdate,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW)=20 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma20,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW)=60 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 59 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma60,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 119 PRECEDING AND CURRENT ROW)=120 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 119 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma120,CASE WHEN COUNT(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW)=250 THEN AVG(b.closePrice) OVER (PARTITION BY b.mktcode,b.tgtcode ORDER BY b.bizdate ROWS BETWEEN 249 PRECEDING AND CURRENT ROW) ELSE NULL END AS ma250 FROM (SELECT mktcode,tgtcode,bizdate,closePrice FROM dsl_rolling_diag_c26c5c6a0208.tail_1 UNION ALL SELECT b.mktcode,b.tgtcode,b.bizdate,b.closePrice FROM newzl.v_hsj_stock_hq_basic b WHERE b.bizdate>'2026-04-13' AND b.bizdate<='2026-04-14') b WHERE b.bizdate<='2026-04-14') w WHERE bizdate='2026-04-14') a;
